const body = $json.body || {};
const cas = Array.isArray(body.cas) ? body.cas : [];
const repetitions = Math.min(Math.max(parseInt(body.repetitions) || 3, 1), 5);
const campagneId = 'camp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
const modesValides = ['exact', 'juge', 'libre'];
const mode = modesValides.includes(body.mode) ? body.mode : 'exact';
const prompt = String(body.prompt || '');
const temperature = typeof body.temperature === 'number' ? body.temperature : 0.7;

const runs = [];
cas.forEach((c, i) => {
  for (let r = 1; r <= repetitions; r++) {
    runs.push({
      campagneId,
      casId: 'cas_' + (i + 1),
      entree: String(c.entree != null ? c.entree : ''),
      attendu: mode === 'libre' ? '' : String(c.attendu != null ? c.attendu : ''),
      repetition: r,
      mode,
      prompt,
      temperature
    });
  }
});

return [{ json: {
  campagneId,
  nom: String(body.nom || 'Campagne sans nom'),
  prompt,
  mode,
  temperature,
  repetitions,
  nbCas: cas.length,
  nbAppels: runs.length,
  runs
} }];
